#!/bin/bash
# Generated by evals/graders/gen_suite.py. Runs (with --scaffold) in the run's
# empty workspace. Copies the fixture project in, without the answer key, and
# makes ~/.claude/skills/rfc3339-ixdtf resolve inside the run's sandbox HOME so the
# skill's absolute paths work.
set -euo pipefail
case_dir="$(cd "$(dirname "$0")" && pwd -P)"
evals_dir="$(cd "$case_dir/../../.." && pwd -P)"
rsync -a --exclude "__pycache__" --exclude ".DS_Store" "$evals_dir/fixtures/tempo/project/" ./
mkdir -p "$HOME/.claude/skills"
ln -sfn "$evals_dir/plugin/skills/rfc3339-ixdtf" "$HOME/.claude/skills/rfc3339-ixdtf"
